CREATE TABLE IF NOT EXISTS uber_rides (id SERIAL PRIMARY KEY, pickup_datetime TIMESTAMP, dropoff_datetime TIMESTAMP, pickup_lat FLOAT, pickup_lng FLOAT, dropoff_lat FLOAT, dropoff_lng FLOAT, fare_amount FLOAT, surge_multiplier FLOAT DEFAULT 1.0, pickup_zone VARCHAR(100) DEFAULT 'Manhattan', status VARCHAR(20) DEFAULT 'completed');
CREATE OR REPLACE FUNCTION usp_GetSurgeAnalysis(p_date date) RETURNS TABLE(hour int, avg_surge numeric, total_rides bigint, avg_fare numeric) AS $$ BEGIN RETURN QUERY SELECT EXTRACT(HOUR FROM pickup_datetime)::int, AVG(surge_multiplier)::numeric, COUNT(*), AVG(fare_amount)::numeric FROM uber_rides WHERE DATE(pickup_datetime)=p_date GROUP BY 1 ORDER BY 1; END; $$ LANGUAGE plpgsql;
